## 2. The preview card (the structurally-identical existing card)

The existing card is **`frontend/components/preview/preview-card.tsx`**, not the page itself. `app/preview/page.tsx` only composes the page; `components/preview/preview-section.tsx` fetches and renders the cards.

### 2.1 `frontend/lib/event-fit.ts` (full file)

```ts
/**
 * The Event Fit's range, mirrored from the server.
 *
 * `shared/constants.py` holds the truth (`EVENT_FIT_SCORE_MIN`, `EVENT_FIT_SCORE_MAX`).
 * The frontend needs the maximum to draw the right number of dots and to say "4 of 5", so
 * it is stated here once rather than typed as a literal beside each use.
 */

export const EVENT_FIT_MIN = 1;
export const EVENT_FIT_MAX = 5;

/** The score, clamped to the range the server promises, so a bad value cannot draw six dots. */
export function clampEventFit(score: number): number {
  if (!Number.isFinite(score)) return EVENT_FIT_MIN;
  return Math.max(EVENT_FIT_MIN, Math.min(EVENT_FIT_MAX, Math.round(score)));
}
```

### 2.2 `frontend/components/preview/preview-card.tsx` — props

```tsx
"use client";

import Link from "next/link";

import type { components } from "@/lib/api/schema";
import { EVENT_FIT_MAX, clampEventFit } from "@/lib/event-fit";
import { EVENT_FIT_TOOLTIP, eventFitLabel, sourceBadge, tagLabel } from "@/lib/preview-labels";
import { utcInstantToLocal } from "@/lib/timezones";

type Card = components["schemas"]["PreviewCardOut"];

export type PreviewCardProps = {
  card: Card;
  /** What the Save button does. The soft wall belongs to the section, not the card. */
  onSave: () => void;
  /** The line under Save after it has been used, if any. */
  savedNote?: string | null;
};

export function PreviewCard({ card, onSave, savedNote = null }: PreviewCardProps) {
```

Key conventions visible here:
- **Named export** function, PascalCase **file name in kebab-case** (`preview-card.tsx`).
- Props type is a **named export** (`PreviewCardProps`) with **doc comments per field**.
- Schema types are aliased locally: `type Card = components["schemas"]["PreviewCardOut"];`
- Default values handled in the destructuring (`savedNote = null`).

### 2.3 The container, indicator, badges, tags, stripe

**Container** (note: **no category stripe** — deliberate, see comment below):

```tsx
<article className="flex flex-col gap-3 rounded-card border border-border-subtle bg-surface-elevated px-5 py-4">
```

**Header row — Event Fit dots on the left, Source Badge on the right:**

```tsx
<div className="flex items-center justify-between gap-3">
  <EventFitDots score={score} tooltipId={tooltipId} />
  <span className="group relative">
    <button
      type="button"
      aria-describedby={badgeTooltipId}
      className={[
        "rounded-control border px-2 py-1 [font:var(--type-scale-meta-sm)]",
        badge.unverified
          ? "border-signal-warn text-signal-warn"
          : "border-border-subtle text-ink-secondary",
      ].join(" ")}
    >
      {badge.unverified ? <span aria-hidden="true">⚠ </span> : null}
      {badge.label}
    </button>
    <Tooltip id={badgeTooltipId}>
      {badge.tooltip} Source: {card.source_name}.
    </Tooltip>
  </span>
</div>
```

**Time row (instant + named IANA zone):**

```tsx
<p className="[font:var(--type-scale-meta-sm)] text-ink-muted">
  {local.date} · {local.time} <span className="text-ink-faint">({zone})</span>
</p>
```

**Headline + link:**

```tsx
<h3 className="[font:var(--type-scale-headline-sm)] text-ink-primary">
  <Link href={`/events/${card.slug}`} className="underline-offset-4 hover:underline">
    {card.title}
  </Link>
</h3>
```

**Venue, then the micro-tag row (middle-dot separated):**

```tsx
{card.venue_name ? (
  <p className="[font:var(--type-scale-body-sm)] text-ink-secondary">{card.venue_name}</p>
) : null}

{card.tags.length > 0 ? (
  <p className="[font:var(--type-scale-microtag)] text-ink-muted">
    {card.tags.map((tag, index) => (
      <span key={tag}>
        {index > 0 ? <span aria-hidden="true"> · </span> : null}
        <span>{tagLabel(tag)}</span>
      </span>
    ))}
  </p>
) : null}
```

**Save row:**

```tsx
<div className="mt-1 flex items-center gap-3">
  <button
    type="button"
    onClick={onSave}
    className="rounded-control border border-border-subtle px-4 py-2 [font:var(--type-scale-meta-md)] text-ink-secondary"
  >
    Save
  </button>
  <span className="[font:var(--type-scale-body-sm)] text-ink-muted">
    {savedNote ?? "We'll hold your seat."}
  </span>
</div>
```

**The indicator (the "5 dots" pattern):**

```tsx
function EventFitDots({ score, tooltipId }: { score: number; tooltipId: string }) {
  return (
    <span className="group relative flex items-center gap-2">
      <button
        type="button"
        aria-label={eventFitLabel(score)}
        aria-describedby={tooltipId}
        className="flex items-center gap-1"
      >
        {Array.from({ length: EVENT_FIT_MAX }, (_, index) => (
          <span
            key={index}
            aria-hidden="true"
            className={[
              "h-1.5 w-1.5 rounded-full",
              index < score ? "bg-ink-primary" : "bg-ink-faint",
            ].join(" ")}
          />
        ))}
      </button>
      <span aria-hidden="true" className="[font:var(--type-scale-meta-sm)] text-ink-muted">
        Event Fit
      </span>
      <Tooltip id={tooltipId}>{EVENT_FIT_TOOLTIP}</Tooltip>
    </span>
  );
}
```

**The hand-rolled tooltip (no library — "UI system: None" is binding):**

```tsx
function Tooltip({ id, children }: { id: string; children: React.ReactNode }) {
  return (
    <span
      role="tooltip"
      id={id}
      className="invisible absolute z-10 mt-1 block max-w-[260px] rounded-card bg-surface-elevated px-3 py-2 shadow-floating [font:var(--type-scale-meta-sm)] text-ink-secondary group-focus-within:visible group-hover:visible"
    >
      {children}
    </span>
  );
}
```

### 2.4 What the existing card deliberately does NOT have (verbatim from its doc comment)

```tsx
/**
 * One Pulse Preview card.
 *
 * **This is deliberately the smallest card the preview needs**, so the Pulse Digest
 * intent can extend it rather than fork it. What it does *not* have is as considered as
 * what it does:
 *
 * - **No category stripe.** Must-know / Nearby / Discovery are digest categories, decided
 *   at composition time from a session. `PreviewCardOut` carries none, and cannot (AD-12)
 *   — so a stripe here would be a category invented on the client.
 * - **No Relevance Pulse.** AD-10 names two indicators that look identical on screen and
 *   forbids substituting one for the other. This page has the session-free **Event Fit**
 *   and says so in as many words.
 * - **No price.** Catalog events have no price field, so nothing here says "free".
 */
```

### 2.5 Label vocabulary lives in `lib/preview-labels.ts`

```ts
const BADGES: Record<string, SourceBadge> = {
  official_site: { label: "Official", tooltip: "Verified venue or organizer." },
  community: { label: "Community", tooltip: "Posted by a community member." },
  aggregator: { label: "Listing site", tooltip: "Aggregated from a public listing." },
  crawled_html: {
    label: "Unverified",
    tooltip: "Read from a public page. We could not confirm it with the organizer.",
    unverified: true,
  },
};

export function sourceBadge(type: string): SourceBadge {
  return BADGES[type] ?? { label: "Listed", tooltip: "Listed from a public source." };
}

export const EVENT_FIT_TOOLTIP =
  "How soon it is, and how complete our details are. The same for everyone — not a personal recommendation.";

export function eventFitLabel(score: number): string {
  return `Event Fit ${score} of ${EVENT_FIT_MAX}`;
}
```

Tags: `tagLabel(key)` — fixed map for `tonight`/`tomorrow`/`this_weekend`, `in_<city>` prefix → `In <City>`, unknown key → title-cased slug (never dropped).

